using KennelPro.Interfaces.Litters; using KennelPro.Models.Enums; using KennelPro.Models.Litters; using KennelPro.Services.Dogs; using KennelPro.Validators;
namespace KennelPro.Services.Reproduction;
public class LitterService { readonly ILitterRepository _repo; readonly DogService _dogs; public LitterService(ILitterRepository repo,DogService dogs){_repo=repo;_dogs=dogs;} public async Task<List<Litter>> GetForCurrentKennelAsync(){var k=await _dogs.GetCurrentKennelIdAsync();return k==null?new():(await _repo.GetByKennelIdAsync(k.Value)).ToList();} public async Task<Litter?> GetByIdAsync(Guid id){var x=await _repo.GetByIdAsync(id);return x!=null&&await _dogs.GetDogForCurrentKennelAsync(x.MotherDogId)!=null&&await _dogs.GetDogForCurrentKennelAsync(x.FatherDogId)!=null?x:null;} async Task<(bool,string)> Check(Litter x){var mother=await _dogs.GetDogForCurrentKennelAsync(x.MotherDogId);var father=await _dogs.GetDogForCurrentKennelAsync(x.FatherDogId);if(mother==null||father==null)return(false,"Parents must belong to your kennel.");if(mother.Gender!=Gender.Female||father.Gender!=Gender.Male)return(false,"Select a mother and a father.");return LitterValidator.Validate(x,out var e)?(true,""):(false,e);} public async Task<(bool,string)> AddAsync(Litter x){var c=await Check(x);if(!c.Item1)return c;x.Id=x.Id==Guid.Empty?Guid.NewGuid():x.Id;await _repo.AddAsync(x);return(true,"");} public async Task<(bool,string)> UpdateAsync(Litter x){if(await GetByIdAsync(x.Id)==null)return(false,"Litter not found.");var c=await Check(x);if(!c.Item1)return c;await _repo.UpdateAsync(x);return(true,"");} public async Task<bool> DeleteAsync(Guid id){if(await GetByIdAsync(id)==null)return false;await _repo.DeleteAsync(id);return true;} }
